python3 - <<'PY'
import re

with open('/app/resources/treasury_bulletin_1939_04_page_61.txt', 'r') as f:
    content = f.read()

rows = re.findall(r'<tr><td>(.*?)</td>(.*?)</tr>', content, re.DOTALL)

def extract_cells(td_content):
    return re.findall(r'<td>(.*?)</td>', td_content)

sections = {}
current_section = None
for label_td, data_td in rows:
    label = label_td.strip()
    cells = extract_cells(data_td)
    if label in ['MOVEMENT IN SHORT-TERM BANKING FUNDS:', 'MOVEMENT IN BROKERAGE BALANCES:',
                 'MOVEMENT IN TRANSACTIONS IN DOMESTIC SECURITIES:', 'MOVEMENT IN TRANSACTIONS IN FOREIGN SECURITIES:',
                 'NET CAPITAL MOVEMENT:']:
        current_section = label.replace('MOVEMENT IN ', '').replace('TRANSACTIONS IN ', '').replace(':', '')
        sections[current_section] = {}
    elif current_section:
        # Weekly keys: may be "1939-Jan. 4" or "Jan. X"
        normalized = label.replace('1939-', '')
        if normalized in ['Jan. 4', 'Jan. 11', 'Jan. 18', 'Jan. 25', 'Feb. 1']:
            sections[current_section][normalized] = cells

LATIN_AMERICA_IDX = 9

print("=== Weekly Latin America data by section ===")
for section_name, weeks in sections.items():
    print(f"\n{section_name}:")
    for week in ['Jan. 4', 'Jan. 11', 'Jan. 18', 'Jan. 25', 'Feb. 1']:
        val = weeks.get(week, ['MISSING'])[LATIN_AMERICA_IDX] if weeks.get(week) else 'MISSING'
        print(f"  {week}: {val}")

# Sum components for NET CAPITAL MOVEMENT
print("\n=== Computed NET CAPITAL MOVEMENT for Latin America ===")
components = ['SHORT-TERM BANKING FUNDS', 'BROKERAGE BALANCES', 'DOMESTIC SECURITIES', 'FOREIGN SECURITIES']

for week in ['Jan. 4', 'Jan. 11', 'Jan. 18', 'Jan. 25', 'Feb. 1']:
    total = 0
    details = []
    for comp in components:
        val_str = sections[comp].get(week, ['0'])[LATIN_AMERICA_IDX]
        if val_str in ['', '-']:
            val = 0
        else:
            val = int(val_str.replace(',', ''))
        total += val
        details.append(val)
    print(f"{week}: banking={details[0]}, broker={details[1]}, domestic={details[2]}, foreign={details[3]} => NET={total}")
PY
